import {
    Table,
    StringColumn,
    IntegerColumn,
    ReferenceColumn,
    BooleanColumn,
    GuidColumn,
    GenericColumn,
    DateTimeColumn,
    DocumentIdColumn,
} from '@servicenow/sdk/core'

export const sys_email = Table({
    actions: ['read', 'update', 'create'],
    allowWebServiceAccess: true,
    attributes: {
        forcePrimaryKeyOrdering: true,
        no_labels: true,
    },
    display: 'subject',
    label: 'Email',
    name: 'sys_email',
    schema: {
        uid: StringColumn({
            label: 'UID',
        }),
        copied: StringColumn({
            label: 'Copied',
            maxLength: 4000,
        }),
        message_id: StringColumn({
            label: 'Message ID',
            maxLength: 1000,
        }),
        sys_updated_by: StringColumn({
            label: [
                {
                    label: 'Updated by',
                    plural: 'Updated by',
                    language: 'en',
                },
            ],
        }),
        recipients: StringColumn({
            label: 'Recipients',
            maxLength: 4000,
        }),
        error_string: StringColumn({
            label: 'Error string',
            maxLength: 1000,
        }),
        body: StringColumn({
            isFullUTF8: true,
            label: 'Body',
            maxLength: 8000,
        }),
        reply_to: StringColumn({
            label: 'Reply to',
            maxLength: 100,
        }),
        receive_type: StringColumn({
            default: 'new',
            dropdown: 'dropdown_with_none',
            label: 'Receive type',
        }),
        sys_mod_count: IntegerColumn({
            label: [
                {
                    label: 'Updates',
                    plural: 'Updates',
                    language: 'en',
                },
            ],
        }),
        user_id: ReferenceColumn({
            label: 'User ID',
            referenceTable: 'sys_user',
        }),
        deleted: BooleanColumn({
            default: false,
            label: 'Deleted',
        }),
        checkpoint: StringColumn({
            label: [
                {
                    hint: 'Checkpoint of the record that triggered this email at the time it was triggered',
                    label: 'Checkpoint',
                    plural: 'Checkpoints',
                    language: 'en',
                },
            ],
        }),
        sys_created_by: StringColumn({
            label: [
                {
                    label: 'Created by',
                    plural: 'Created by',
                    language: 'en',
                },
            ],
        }),
        notification_type: StringColumn({
            default: 'SMTP',
            dropdown: 'dropdown_with_none',
            label: 'Notification type',
        }),
        status: StringColumn({
            label: 'Status',
            maxLength: 1000,
        }),
        type: StringColumn({
            attributes: {
                'glide.db.oracle.ps.query': false,
            },
            default: 'received',
            dropdown: 'dropdown_with_none',
            label: 'Type',
        }),
        direct: StringColumn({
            label: [
                {
                    hint: 'Direct (To:) recipients of this email',
                    label: 'To',
                    plural: 'Tos',
                    language: 'en',
                },
            ],
            maxLength: 4000,
        }),
        importance: StringColumn({
            label: 'Importance',
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                    language: 'en',
                },
            ],
            primary: true,
        }),
        body_text: StringColumn({
            isFullUTF8: true,
            label: 'Body text',
            maxLength: 8000,
        }),
        content_type: StringColumn({
            label: 'Content type',
            maxLength: 1000,
        }),
        target_table: GenericColumn({
            columnType: 'short_table_name',
            label: [
                {
                    hint: 'Table of the record associated with this email',
                    label: 'Target table',
                    plural: 'Target tables',
                    language: 'en',
                },
            ],
        }),
        subject: StringColumn({
            attributes: {
                no_truncate: true,
            },
            isFullUTF8: true,
            label: 'Subject',
            maxLength: 160,
        }),
        headers: StringColumn({
            label: 'Headers',
            maxLength: 8000,
        }),
        weight: IntegerColumn({
            default: '0',
            label: [
                {
                    hint: 'Weight of the email notification that created this email',
                    label: 'Weight',
                    plural: 'Weights',
                    language: 'en',
                },
            ],
        }),
        sys_created_on: DateTimeColumn({
            label: [
                {
                    label: 'Created',
                    plural: 'Created',
                    language: 'en',
                },
            ],
        }),
        user: StringColumn({
            label: [
                {
                    hint: 'User email address',
                    label: 'User',
                    plural: 'Users',
                    language: 'en',
                },
            ],
            maxLength: 254,
        }),
        blind_copied: StringColumn({
            label: 'Blind copied',
            maxLength: 4000,
        }),
        instance: DocumentIdColumn({
            dependent: 'target_table',
            label: [
                {
                    hint: 'The record that was created or updated by this email',
                    label: 'Target',
                    plural: 'Targets',
                    language: 'en',
                },
            ],
        }),
        sys_updated_on: DateTimeColumn({
            label: [
                {
                    label: 'Updated',
                    plural: 'Updated',
                    language: 'en',
                },
            ],
        }),
        mailbox: ReferenceColumn({
            label: 'Mailbox',
            referenceTable: 'sys_mailbox',
        }),
        state: StringColumn({
            default: 'ready',
            choices: {
                processed: {
                    label: 'Processed',
                },
                ignored: {
                    label: 'Ignored',
                },
                error: {
                    label: 'Error',
                },
                ready: {
                    label: 'Ready',
                },
            },
            dropdown: 'dropdown_without_none',
            label: 'State',
        }),
    },
})
